* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #eef1f5;
  color: #171a21;
  font-family: Inter, Arial, sans-serif;
}

.dashboard {
  padding: 18px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.header span {
  color: #2563eb;
  font-size: 11px;
  font-weight: 800;
}

.header h1 {
  margin: 4px 0;
  font-size: 25px;
}

.header p {
  margin: 0;
  color: #697282;
  font-size: 11px;
}

.actions {
  display: flex;
  gap: 8px;
}

button {
  border: 0;
  border-radius: 5px;
  padding: 10px 18px;
  background: #1d4ed8;
  color: white;
  font-weight: 700;
  cursor: pointer;
}

button.secondary {
  background: white;
  border: 1px solid #cbd2dc;
  color: #171a21;
}

.filters {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 14px;
  padding: 12px;
  background: white;
  border: 1px solid #dce1e8;
}

.filters label {
  color: #697282;
  font-size: 10px;
  font-weight: 700;
}

input, select {
  width: 100%;
  margin-top: 5px;
  padding: 9px;
  border: 1px solid #cbd2dc;
  background: white;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 9px;
  margin-bottom: 14px;
}

.metrics article {
  padding: 13px;
  background: white;
  border: 1px solid #dce1e8;
  border-top: 3px solid #2563eb;
}

.metrics span {
  display: block;
  color: #697282;
  font-size: 9px;
  text-transform: uppercase;
}

.metrics strong {
  display: block;
  margin-top: 7px;
  font-size: 20px;
}

.metrics .danger {
  border-top-color: #dc2626;
}

.metrics .warning {
  border-top-color: #d97706;
}

.layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 12px;
}

.panel {
  min-width: 0;
  padding: 13px;
  background: white;
  border: 1px solid #dce1e8;
}

.panel.large {
  grid-column: span 1;
}

.panel h2 {
  margin: 0 0 11px;
  font-size: 13px;
}

.chart {
  width: 100%;
  height: 230px;
}

.chart-line {
  fill: none;
  stroke: #2563eb;
  stroke-width: 3;
}

.chart circle {
  fill: white;
  stroke: #dc2626;
  stroke-width: 3;
}

.alerts {
  display: grid;
  gap: 7px;
}

.alert {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px;
  border-left: 4px solid #2563eb;
  background: #f7f8fa;
}

.alert.high {
  border-color: #dc2626;
}

.alert.medium {
  border-color: #d97706;
}

.alert div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.alert strong {
  font-size: 10px;
}

.alert span {
  color: #697282;
  font-size: 8px;
}

.alert b {
  font-size: 18px;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 9px;
}

th, td {
  padding: 7px;
  border-bottom: 1px solid #e3e7ed;
  text-align: left;
}

th {
  color: #697282;
  font-size: 8px;
  text-transform: uppercase;
}

.empty {
  padding: 25px 10px;
  color: #697282;
  font-size: 10px;
  text-align: center;
}

@page {
  size: A4 landscape;
  margin: 8mm;
}
@media print {
  body, .dashboard {
    background: white;
    padding: 0;
  }
  .no-print {
    display: none !important;
  }
  .panel, .metrics article {
    break-inside: avoid;
  }
}

